async function loadMore() {
  const items = await fetchMoreItems();
  renderItems(items);
  if ("requestResize" in window) {
    window.requestResize();
  }
}

.widget {
  width: 100%;
  height: 500px;
}

@supports (frame-sizing: content-height) {
  .widget {
    height: auto;
    frame-sizing: content-height;
  }
}
